arguments.new_str:
using Microsoft.VisualStudio.TestTools.UnitTesting;
namespace MyApp.Tests;

[TestClass]
public sealed class OrderTests
{
    private static DbFixture? s_fixture;

    [ClassInitialize]
    public static void ClassInit(TestContext context) => s_fixture = new DbFixture();

    [ClassCleanup]
    public static void ClassCleanup() => s_fixture?.Dispose();

    [TestMethod]
    public void Fixture_HasConnectionString()
    {
        Assert.IsNotNull(s_fixture!.ConnectionString);
    }
}

// MSTest defaults to serial execution across classes (unlike xUnit, which parallelizes
// classes by default), so this attribute is required to match the project's previous
// xUnit parallel-class behaviour. Without it, the suite would still pass but run
// roughly one-class-at-a-time and CI throughput would drop.
[assembly: Parallelize(Workers = 0, Scope = ExecutionScope.ClassLevel)]

